-- Publish them. Done as a separate statement so a re-run republishes anything
-- an operator archived without resurrecting their own entries.
UPDATE public.template_library_entries
SET status = 'published',
    published_at = COALESCE(published_at, now())
WHERE version = 1
  AND status = 'draft'
  AND slug IN ($tlt$investor-compass$tlt$, $tlt$executive-brief$tlt$, $tlt$property-snapshot$tlt$, $tlt$due-diligence-dossier$tlt$, $tlt$suburb-market-compass$tlt$, $tlt$suburb-snapshot$tlt$, $tlt$postcode-market-analysis$tlt$, $tlt$statewide-market-review$tlt$, $tlt$property-comparison-matrix$tlt$, $tlt$ten-year-cash-flow-projection$tlt$, $tlt$client-fact-find$tlt$, $tlt$compliance-file-review$tlt$, $tlt$off-market-opportunity-brief$tlt$, $tlt$renovation-uplift-analysis$tlt$, $tlt$first-home-buyer-report$tlt$, $tlt$smsf-property-assessment$tlt$, $tlt$commercial-property-assessment$tlt$, $tlt$development-feasibility-study$tlt$, $tlt$portfolio-review$tlt$, $tlt$suburb-executive-brief$tlt$, $tlt$suburb-growth-drivers$tlt$, $tlt$suburb-rental-market-report$tlt$, $tlt$postcode-executive-brief$tlt$, $tlt$postcode-snapshot$tlt$, $tlt$statewide-executive-brief$tlt$, $tlt$statewide-snapshot$tlt$, $tlt$two-property-head-to-head$tlt$, $tlt$buy-vs-hold-comparison$tlt$, $tlt$portfolio-comparison$tlt$, $tlt$cash-flow-snapshot$tlt$, $tlt$negative-gearing-analysis$tlt$, $tlt$equity-position-report$tlt$, $tlt$buyer-brief-form$tlt$, $tlt$risk-profile-questionnaire$tlt$, $tlt$client-onboarding-pack$tlt$, $tlt$property-inspection-checklist$tlt$, $tlt$aml-kyc-verification-record$tlt$, $tlt$advice-record-and-disclosure$tlt$, $tlt$annual-compliance-attestation$tlt$, $tlt$complaints-register-report$tlt$, $tlt$cash-flow-ledger$tlt$, $tlt$cash-flow-matrix$tlt$, $tlt$cash-flow-position$tlt$);
